function checkinSummary(dates:string[],today:string){const set=new Set(dates);let cursor=set.has(today)?today:new Date(Date.parse(today+"T00:00:00Z")-86400000).toISOString().slice(0,10);let streak=0;while(set.has(cursor)){streak++;cursor=new Date(Date.parse(cursor+"T00:00:00Z")-86400000).toISOString().slice(0,10);}const days=Array.from({length:7},(_,i)=>{const date=new Date(Date.parse(today+"T00:00:00Z")+i*86400000).toISOString().slice(0,10);return {date,checked_in:set.has(date)};});return {today,days,streak,total_checkins:dates.length,checked_in_today:set.has(today)};}

